import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"How the bot works","description":"The full DLMM Bot pipeline for newcomers — scan, vet, enter, manage, exit — plus the three sleeves and follow mode.","frontmatter":{"title":"How the bot works","description":"The full DLMM Bot pipeline for newcomers — scan, vet, enter, manage, exit — plus the three sleeves and follow mode."},"headers":[],"relativePath":"how-it-works.md","filePath":"how-it-works.md","lastUpdated":1786714041000}'),s={name:"how-it-works.md"};function n(i,e,l,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="how-the-bot-works" tabindex="-1">How the bot works <a class="header-anchor" href="#how-the-bot-works" aria-label="Permalink to &quot;How the bot works&quot;">​</a></h1><p>DLMM Bot is an automated liquidity-provider (LP) bot for <a href="https://meteora.ag" target="_blank" rel="noreferrer">Meteora DLMM</a> pools on Solana. In one sentence: <strong>it parks SOL in bins just under a hot token&#39;s price, earns a fee every time traders move through those bins, and cashes back to SOL by fixed mechanical rules.</strong></p><p>Think of it like a market stall under the current price: shoppers (traders) walk through our bins, we collect a tiny fee each time, and we leave when the rules say leave — not when we &quot;feel&quot; like it.</p><div class="warning custom-block"><p class="custom-block-title">Risk first</p><p>Memecoin LP can wipe a wallet. The bot is built defense-first (paper mode by default, hard safety gates, mechanical stops), but it cannot catch every rug. <strong>Burner wallet only. Not financial advice.</strong> See <a href="./risk">Risk &amp; sizing</a>.</p></div><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><p>Everything runs from one tick loop:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scan → vet → enter → manage → exit</span></span>
<span class="line"><span>  ↑                              │</span></span>
<span class="line"><span>  └──────── capital rotates ─────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Stage</th><th>What happens</th><th>How often</th></tr></thead><tbody><tr><td><strong>Scan</strong></td><td>Sweep Meteora&#39;s pool list for busy SOL-quoted pools; dedupe copycat tickers; apply hard pool gates (TVL, fees, volume, base fee); score survivors 0–100</td><td>Every 60s</td></tr><tr><td><strong>Vet</strong></td><td>Fresh on-chain + RugCheck checks on the token itself: authorities revoked, holder concentration, insider clusters, creator rug history, age window</td><td>At entry time</td></tr><tr><td><strong>Enter</strong></td><td>Open a <strong>one-sided SOL</strong> position below the current price (BidAsk shape for memes, Spot for majors), sized by Kelly + score, within rent budgets</td><td>When a candidate passes everything and a slot is free</td></tr><tr><td><strong>Manage</strong></td><td>Poll each open position and walk the P0→P5 priority ladder: safety exits, stop loss, rotation, take-profit, fee claims, below-range handling</td><td>Every 15s</td></tr><tr><td><strong>Exit</strong></td><td>Close the position, swap any leftover tokens back to SOL (Zap SDK, Jupiter fallback), record measured PnL in SQLite</td><td>When a rule fires — never on gut feel</td></tr></tbody></table><p>Two design choices run through all of it:</p><ul><li><strong>SOL is the unit of account.</strong> Wins and losses are measured in SOL that actually left and returned to the wallet — not notional marks, not USD screenshots.</li><li><strong>Rules beat gut feel.</strong> The bot has no whale chat to consult. Wherever a human trader would &quot;ask the group,&quot; the bot takes the strictly more defensive branch.</li></ul><h2 id="why-one-sided-sol-below-price" tabindex="-1">Why one-sided SOL below price? <a class="header-anchor" href="#why-one-sided-sol-below-price" aria-label="Permalink to &quot;Why one-sided SOL below price?&quot;">​</a></h2><p>The default entry never buys the token up front. The bot places only SOL, in bins <strong>below</strong> the current price:</p><ol><li>If price <strong>dips</strong> into the range, the bins mechanically buy tokens on the way down (cheaper each bin).</li><li>If price <strong>recovers</strong> back up through the range, the same bins sell those tokens back for SOL — above the acquisition price — plus every trade paid a fee.</li><li>If price <strong>never visits</strong> the range, the SOL just sits there untouched: no profit, but no loss either (only idle capital and a little rent).</li></ol><p>The bot is not guessing the top. It waits for price to come to it, earns the round trip, and leaves.</p><h2 id="the-three-sleeves" tabindex="-1">The three sleeves <a class="header-anchor" href="#the-three-sleeves" aria-label="Permalink to &quot;The three sleeves&quot;">​</a></h2><p>One scanner pipeline, three playbooks. The <strong>sleeve</strong> is stamped on each position at entry and decides its range shape, sizing, and manage rules.</p><table tabindex="0"><thead><tr><th>Sleeve</th><th>What it trades</th><th>Range shape</th><th>Sizing (current defaults)</th></tr></thead><tbody><tr><td><strong>micro</strong></td><td>Very young/small memes, mcap $100k–$200k</td><td>BidAsk below price</td><td>0.5× the core Kelly size, max 0.45 SOL, at most <strong>1</strong> slot, ≤5% of wallet total — loss budget first</td></tr><tr><td><strong>meme</strong></td><td>The main book: memes, mcap ≥ $200k</td><td>BidAsk below price</td><td>Kelly × score multiplier; the bread-and-butter strategy</td></tr><tr><td><strong>majors</strong></td><td>Allowlisted SOL-quoted alts (PUMP, JTO, BONK, WIF, RAY, JUP, …)</td><td><strong>Spot</strong> (uniform bins, 12% below / 6% above price)</td><td>Fixed 0.75 SOL, max 1 slot, separate slower manage rules</td></tr></tbody></table><p>Majors run <strong>after</strong> meme entries each tick, and only when at least <code>meme_reserve_slots</code> (2) remain free — hot memes always keep headroom. Stable pairs like SOL‑USDC are permanently out of scope, not a &quot;later&quot; feature.</p><h2 id="managing-a-position-the-p0→p5-ladder" tabindex="-1">Managing a position: the P0→P5 ladder <a class="header-anchor" href="#managing-a-position-the-p0→p5-ladder" aria-label="Permalink to &quot;Managing a position: the P0→P5 ladder&quot;">​</a></h2><p>Every open position is checked top-to-bottom against a priority ladder every 15 seconds. <strong>First match wins — a higher rule always preempts a lower one.</strong></p><table tabindex="0"><thead><tr><th>Rule</th><th>Name</th><th>One-liner</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>Safety exit</td><td>Rug signals → close <em>now</em>, dump token to SOL, blacklist token + creator</td></tr><tr><td><strong>P1</strong></td><td>Stop loss</td><td>Position worth &lt; 75% of entry in SOL → close, take the loss</td></tr><tr><td><strong>P2</strong></td><td>Rotation</td><td>Fees/volume went cold, or position too old → free the slot</td></tr><tr><td><strong>P3</strong></td><td>Above range</td><td>Price climbed out the top → take profit (or exit slowly if it never visited us)</td></tr><tr><td><strong>P4</strong></td><td>In range</td><td>Earning: claim/bank fees, maybe profit-lock a slice, escape hatch</td></tr><tr><td><strong>P5</strong></td><td>Below range</td><td>100% token after a short grace → close, swap to SOL, cool down</td></tr></tbody></table><p>Full details with every threshold: <a href="./strategy">Strategy reference</a>.</p><h2 id="follow-mode-careful-re-entry" tabindex="-1">Follow mode (careful re-entry) <a class="header-anchor" href="#follow-mode-careful-re-entry" aria-label="Permalink to &quot;Follow mode (careful re-entry)&quot;">​</a></h2><p>After a clean up-and-out close (P3), the token often keeps running. Follow mode may re-enter the same token — but only through deliberately picky gates, because simulation over recorded price paths showed unguarded chasing loses money:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P3 close ──arms──▶ wait for: hot volume (≥$100k/30m)</span></span>
<span class="line"><span>                          + 15% retrace from the peak</span></span>
<span class="line"><span>                          + fresh token vetting</span></span>
<span class="line"><span>                └──▶ open a tighter leg (30% deep, 0.25 SOL)</span></span>
<span class="line"><span>                └──▶ re-arm only after a NEW chain high (up-only)</span></span>
<span class="line"><span>                └──▶ chain ends on: any non-P3 close, 3 legs,</span></span>
<span class="line"><span>                     −0.075 SOL cumulative loss, cold volume, or 12h</span></span></code></pre></div><p>While a follow chain owns a token, the normal scanner skips it — one owner of re-entry timing per token. See <a href="./strategy#p3-f-follow-mode">Strategy reference → Follow mode</a>.</p><h2 id="paper-vs-live" tabindex="-1">Paper vs live <a class="header-anchor" href="#paper-vs-live" aria-label="Permalink to &quot;Paper vs live&quot;">​</a></h2><ul><li><strong>Paper (default):</strong> the full brain runs — real scanning, real vetting, real pool data — but fills are simulated. Identical database records, flagged <code>paper</code>. No wallet needed.</li><li><strong>Live:</strong> real SOL. Deliberately double-locked: it requires <strong>both</strong> <code>FARMER_MODE=live</code> in the environment <strong>and</strong> <code>[exec] mode = &quot;live&quot;</code> in config. One switch alone stays safe.</li></ul><p>The built-in promotion gate: <code>npm run status</code> tracks consecutive profitable paper days and marks you <strong>eligible</strong> after 7. See <a href="./risk#paper-first-the-promotion-gate">Risk &amp; sizing → Paper first</a>.</p><h2 id="what-s-actually-running" tabindex="-1">What&#39;s actually running <a class="header-anchor" href="#what-s-actually-running" aria-label="Permalink to &quot;What&#39;s actually running&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Process</th><th>Job</th></tr></thead><tbody><tr><td><strong>Farmer</strong></td><td>The tick loop — scans, vets, opens, manages, closes. The strategy lives here.</td></tr><tr><td><strong>Dashboard</strong></td><td>The web UI: live positions, charts, HALT button, settings, the in-app Wiki.</td></tr><tr><td><strong>Deploy watcher</strong> (optional, PM2 path)</td><td>Pulls new builds from GitHub — automatically, or after you Approve.</td></tr><tr><td><strong>SQLite + config</strong></td><td><code>data/farmer.db</code> (positions, decisions, errors) and <code>data/config.toml</code> (your knobs, hot-reloaded).</td></tr></tbody></table><p>The chain is the source of truth: on every startup the bot enumerates the wallet&#39;s actual on-chain DLMM positions, diffs against the database, and repairs the DB to match.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./strategy">Strategy reference</a> — every gate, threshold, and exit rule</li><li><a href="./risk">Risk &amp; sizing</a> — Kelly, brakes, HALT/PAUSE, promotion gate</li><li><a href="./configuration">Configuration reference</a> — every knob in <code>config.toml</code></li><li><a href="./dashboard">Dashboard guide</a> — tab-by-tab tour</li><li><a href="./easy">Easy setup (Railway)</a> · <a href="./advanced">Advanced setup</a></li></ul>`,34)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
